package com.auth.service;

import com.auth.entity.Token;
import com.auth.repository.TokenRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Duration;
import java.time.Instant;

@Service
public class AuthService {

    private final TokenRepository tokenRepository;

    public AuthService(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    // Issue all three tokens on login
    public void issueTokens(String userId) {
        String accessToken = generateToken();
        String refreshToken = generateToken();
        String oneTimeToken = generateToken();

        // Create Access Token (10 minutes)
        Token accessToken = new Token();
        accessToken.setTokenValue(accessToken);
        accessToken.setUserId(userId);
        accessToken.setTokenType("ACCESS");
        accessToken.setIssuedAt(Instant.now());
        accessToken.setExpiresAt(Instant.now().plusMinutes(10));
        accessToken.setRevoked(false);
        accessToken.setConsumed(false);
        tokenRepository.save(accessToken);

        // Create Refresh Token (24 hours)
        Token refreshTokenObj = new Token();
        refreshTokenObj.setTokenValue(refreshToken);
        refreshTokenObj.setUserId(userId);
        refreshTokenObj.setTokenType("REFRESH");
        refreshTokenObj.setIssuedAt(Instant.now());
        refreshTokenObj.setExpiresAt(Instant.now().plusDays(1));
        refreshTokenObj.setRevoked(false);
        refreshTokenObj.setConsumed(false);
        tokenRepository.save(refreshTokenObj);

        // Create One-Time Token (5 minutes max)
        Token oneTimeTokenObj = new Token();
        oneTimeTokenObj.setTokenValue(oneTimeToken);
        oneTimeTokenObj.setUserId(userId);
        oneTimeTokenObj.setTokenType("ONETIME");
        oneTimeTokenObj.setIssuedAt(Instant.now());
        oneTimeTokenObj.setExpiresAt(Instant.now().plusMinutes(5)); // max 5 min
        oneTimeTokenObj.setRevoked(false);
        oneTimeTokenObj.setConsumed(false);
        tokenRepository.save(oneTimeTokenObj);
    }

    private String generateToken() {
        return java.util.UUID.randomUUID().toString();
    }

    // Renew endpoint logic - check refresh token and rotate
    @Transactional
    public String renewRefreshToken(String refreshTokenValue) {
        // Find the refresh token
        Token existingRefresh = tokenRepository.findByTokenValueAndTokenType(refreshTokenValue, "REFRESH")
                .orElseThrow(() -> new RuntimeException("Refresh token not found"));

        // Check if it's expired or revoked
        if (existingRefresh.isRevoked()) {
            throw new RuntimeException("Refresh token is revoked");
        }
        if (existingRefresh.getExpiresAt().isBefore(Instant.now())) {
            throw new RuntimeException("Refresh token is expired");
        }

        // Now atomically revoke it and create new tokens
        // We need to update the existing token to revoked status
        existingRefresh.setRevoked(true);
        tokenRepository.save(existingRefresh); // This updates isRevoked to true

        // Generate new tokens
        String newRefreshToken = generateToken();
        String newAccessToken = generateToken();

        // Save new refresh token
        Token newRefreshTokenObj = new Token();
        newRefreshTokenObj.setTokenValue(newRefreshToken);
        newRefreshTokenObj.setUserId(existingRefresh.getUserId());
        newRefreshTokenObj.setTokenType("REFRESH");
        newRefreshTokenObj.setIssuedAt(Instant.now());
        newRefreshTokenObj.setExpiresAt(Instant.now().plusDays(1));
        newRefreshTokenObj.setRevoked(false);
        newRefreshTokenObj.setConsumed(false);
        tokenRepository.save(newRefreshTokenObj);

        // Save new access token
        Token newAccess = new Token();
        newAccess.setTokenValue(newAccessToken);
        newAccess.setUserId(existingRefresh.getUserId());
        newAccess.setTokenType("ACCESS");
        newAccess.setIssuedAt(Instant.now());
        newAccess.setExpiresAt(Instant.now().plusMinutes(10));
        newAccess.setRevoked(false);
        newAccess.setConsumed(false);
        tokenRepository.save(newAccess);

        return newAccessToken;
    }

    // Validate and consume one-time token
    @Transactional
    public boolean validateOneTimeToken(String tokenValue) {
        Token oneTimeToken = tokenRepository.findByTokenValueAndTokenType(tokenValue, "ONETIME")
                .orElse(null);

        if (oneTimeToken == null) {
            return false;
        }

        if (oneTimeToken.isRevoked()) {
            return false;
        }
        if (oneTimeToken.isConsumed()) {
            return false;
        }
        if (oneTimeToken.getExpiresAt().isBefore(Instant.now())) {
            return false;
        }

        // All checks passed - atomically mark as consumed
        oneTimeToken.setConsumed(true);
        tokenRepository.save(oneTimeToken);
        return true;
    }

    // Logout - revoke all tokens for user
    @Transactional
    public void logout(String userId) {
        // Find all tokens for this user and revoke them
        // Actually the requirement says "Invalidate all tokens for the authenticated user."
        // This likely means setting isRevoked = true for all their tokens
        List<Token> userTokens = tokenRepository.findByUserId(userId);
        for (Token token : userTokens) {
            token.setRevoked(true);
            tokenRepository.save(token); // This will update each token individually
        }
    }
}
EOF"}

