package com.auth.repository;

import com.auth.entity.Token;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.time.Instant;
import java.util.List;
import java.util.Optional;

@Repository
public interface TokenRepository extends JpaRepository<Token, Long> {
    Optional<Token> findByTokenValue(String tokenValue);
    Optional<Token> findByTokenValueAndTokenType(String tokenValue, String tokenType);
    List<Token> findByUserId(String userId);

    // Find refresh token that is valid (not revoked, not expired)
    @Query("SELECT t FROM Token t WHERE t.tokenValue = :token AND t.tokenType = 'REFRESH' AND t.isRevoked = false AND t.expiresAt > :now")
    Optional<Token> findValidRefreshToken(@Param("token") String token, @Param("now") Instant now);

    // Atomically revoke refresh token if valid - returns true if revoked, false if not found or already revoked/expired
    @Modifying
    @Query("UPDATE Token t SET t.isRevoked = true WHERE t.tokenValue = :token AND t.tokenType = 'REFRESH' AND t.isRevoked = false AND t.expiresAt > :now")
    int revokeRefreshTokenIfValid(@Param("token") String token, @Param("now") Instant now);

    // Delete expired/revoked/consumed tokens
    @Modifying
    @Query("DELETE FROM Token t WHERE t.expiresAt < :now OR t.isRevoked = true OR t.isConsumed = true")
    int deleteExpiredTokens(@Param("now") Instant now);
}
EOF"}

