        accessTokenToken.setIssuedAt(Instant.now());
        accessTokenToken.setExpiresAt(Instant.now().plusMinutes(10));
        accessTokenToken.setRevoked(false);
        accessTokenToken.setConsumed(false);
        tokenRepository.save(accessTokenToken);

        // Create Refresh Token (24 hours)
        Token refreshTokenToken = new Token();
        refreshTokenToken.setTokenValue(refreshToken);
        refreshTokenToken.setUserId(userId);
        refreshTokenToken.setTokenType("REFRESH");
        refreshTokenToken.setIssuedAt(Instant.now());
        refreshTokenToken.setExpiresAt(Instant.now().plusDays(1));
        refreshTokenToken.setRevoked(false);
        refreshTokenToken.setConsumed(false);
        tokenRepository.save(refreshTokenToken);

        // Create One-Time Token (5 minutes)
        Token oneTimeTokenObj = new Token();
        oneTimeTokenObj.setTokenValue(oneTimeToken);
        oneTimeTokenObj.setUserId(userId);
        oneTimeTokenObj.setTokenType("ONETIME");
        oneTimeTokenObj.setIssuedAt(Instant.now());
        oneTimeTokenObj.setExpiresAt(Instant.now().plusMinutes(5)); // max 5 min
        oneTimeTokenObj.setRevoked(false);
        oneTimeTokenObj.setConsumed(false);
