                .orElse(null);

        if (oneTimeToken == null) {
            return false;
        }

        if (oneTimeToken.isRevoked()) {
            return false;
        }
        if (oneTimeToken.isConsumed()) {
            return false;
        }
        if (oneTimeToken.getExpiresAt().isBefore(Instant.now())) {
            return false;
        }

        // All checks passed - atomically mark as consumed
        oneTimeToken.setConsumed(true);
        tokenRepository.save(oneTimeToken);
        return true;
    }

    // Logout - revoke all tokens for user
    @Transactional
    public void logout(String userId) {
        List<Token> userTokens = tokenRepository.findByUserId(userId);
        for (Token token : userTokens) {
            token.setRevoked(true);
            tokenRepository.save(token);
        }
