package com.auth.controller;

import com.auth.dto.LoginRequest;
import com.auth.service.AuthService;
import jakarta.servlet.http.Cookie;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.HashMap;
import java.util.Map;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request) {
        if (request.getUsername() == null || request.getUsername().trim().isEmpty() ||
            request.getPassword() == null || request.getPassword().trim().isEmpty()) {
            return ResponseEntity.badRequest().body(Map.of("error", "Username or password is missing"));
        }

        // Issue tokens with username as userId
        AuthService.IssueTokensResponse response = authService.loginIssueTokens(request.getUsername());

        Map<String, Object> body = new HashMap<>();
        body.put("accessToken", response.getAccessToken());
        body.put("oneTimeToken", response.getOneTimeToken());

        // Set refresh token cookie
        String cookieValue = "refreshToken=" + response.getRefreshToken() + "; HttpOnly; Max-Age=86400; Path=/";
        return ResponseEntity.ok()
            .header("Set-Cookie", cookieValue)
            .body(body);
    }

    @PostMapping("/renew")
    public ResponseEntity<?> renew(@CookieValue(name = "refreshToken", required = false) String cookieRefreshToken,
                                   @RequestHeader(name = "refreshToken", required = false) String headerRefreshToken) {
        // If both are present, cookie takes precedence
        String refreshTokenValue = null;
        if (cookieRefreshToken != null && !cookieRefreshToken.isEmpty()) {
            refreshTokenValue = cookieRefreshToken;
        } else if (headerRefreshToken != null && !headerRefreshToken.isEmpty()) {
            refreshTokenValue = headerRefreshToken;
        }

        if (refreshTokenValue == null || refreshTokenValue.trim().isEmpty()) {
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", "Refresh token is missing"));
        }

        try {
            AuthService.RenewResponse renewResp = authService.renewRefreshToken(refreshTokenValue);
            Map<String, Object> body = new HashMap<>();
            body.put("accessToken", renewResp.getAccessToken());
            // Set new refresh token cookie
            String cookieValue = "refreshToken=" + renewResp.getRefreshToken() + "; HttpOnly; Max-Age=86400; Path=/";
            return ResponseEntity.ok()
                .header("Set-Cookie", cookieValue)
                .body(body);
        } catch (RuntimeException e) {
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", e.getMessage()));
        }
    }

    @PostMapping("/logout")
    public ResponseEntity<?> logout(@RequestHeader("Authorization") String authorizationHeader) {
        if (authorizationHeader == null || !authorizationHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(401).body(Map.of("message", "Missing or invalid Authorization header"));
        }
        String accessTokenValue = authorizationHeader.substring(7); // Remove "Bearer " prefix

        try {
            authService.logout(accessTokenValue);
            return ResponseEntity.ok().body(Map.of("message", "Logged out successfully"));
        } catch (RuntimeException e) {
            return ResponseEntity.status(401).body(Map.of("message", e.getMessage()));
        }
    }

    @PostMapping("/validate-token")
    public ResponseEntity<?> validateToken(@RequestBody Map<String, String> request) {
        String tokenValue = request.get("token");
        if (tokenValue == null || tokenValue.trim().isEmpty()) {
            return ResponseEntity.status(400).body(Map.of("valid", false, "message", "token parameter is missing"));
        }

        boolean isValid = authService.validateOneTimeToken(tokenValue);
        if (isValid) {
            return ResponseEntity.ok(Map.of("valid", true, "message", "Token validated and consumed"));
        } else {
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", "Token is invalid, expired, revoked, or consumed"));
        }
    }
}
EOF"}

