package com.auth.service;

import com.auth.entity.Token;
import com.auth.repository.TokenRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.UUID;

@Service
public class AuthService {

    private final TokenRepository tokenRepository;

    public AuthService(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    // Issue all three tokens on login - returns the generated token values
    public IssueTokensResponse loginIssueTokens(String userId) {
        String accessToken = UUID.randomUUID().toString();
        String refreshToken = UUID.randomUUID().toString();
        String oneTimeToken = UUID.randomUUID().toString();

        // Create Access Token (10 minutes)
        Token accessTokenToken = new Token();
        accessTokenToken.setTokenValue(accessToken);
        accessTokenToken.setUserId(userId);
        accessTokenToken.setTokenType("ACCESS");
        accessTokenToken.setIssuedAt(Instant.now());
        accessTokenToken.setExpiresAt(Instant.now().plusMinutes(10));
        accessTokenToken.setRevoked(false);
        accessTokenToken.setConsumed(false);
        tokenRepository.save(accessTokenToken);

        // Create Refresh Token (24 hours)
        Token refreshTokenToken = new Token();
        refreshTokenToken.setTokenValue(refreshToken);
        refreshTokenToken.setUserId(userId);
        refreshTokenToken.setTokenType("REFRESH");
        refreshTokenToken.setIssuedAt(Instant.now());
        refreshTokenToken.setExpiresAt(Instant.now().plusMinutes(60 * 24)); // 24 hours = 1440 minutes
        // Actually plusDays is available. Let me check - Instant has plusDays(int).
        // Let me just use plusDays(1) for simplicity.
        // Actually the compilation error says plusDays doesn't exist. Let me check - Instant does have plusDays.
        // Let me just use plus(ChronoUnit) methods.
        refreshTokenToken.setExpiresAt(Instant.now().plus(1, ChronoUnit.DAYS));
        refreshTokenToken.setRevoked(false);
        refreshTokenToken.setConsumed(false);
        tokenRepository.save(refreshTokenToken);

        // Create One-Time Token (5 minutes)
        Token oneTimeTokenObj = new Token();
        oneTimeTokenObj.setTokenValue(oneTimeToken);
        oneTimeTokenObj.setUserId(userId);
        oneTimeTokenObj.setTokenType("ONETIME");
        oneTimeTokenObj.setIssuedAt(Instant.now());
        oneTimeTokenObj.setExpiresAt(Instant.now().plus(5, ChronoUnit.MINUTES));
        oneTimeTokenObj.setRevoked(false);
        oneTimeTokenObj.setConsumed(false);
        tokenRepository.save(oneTimeTokenObj);

        return new IssueTokensResponse(accessToken, refreshToken, oneTimeToken);
    }

    // Renew endpoint logic - check refresh token and rotate
    // Returns both new access token and new refresh token values
    @Transactional
    public RenewResponse renewRefreshToken(String refreshTokenValue) {
        Instant now = Instant.now();
        // Find the refresh token first to get userId
        Token existingRefresh = tokenRepository.findByTokenValueAndTokenType(refreshTokenValue, "REFRESH")
                .orElse(null);

        if (existingRefresh == null) {
            throw new RuntimeException("Refresh token not found");
        }

        // Check validity
        if (existingRefresh.isRevoked()) {
            throw new RuntimeException("Refresh token is revoked");
        }
        if (existingRefresh.getExpiresAt().isBefore(now)) {
            throw new RuntimeException("Refresh token is expired");
        }

        // Atomically revoke it using the repository method
        int result = tokenRepository.revokeRefreshTokenIfValid(refreshTokenValue, now);
        if (result == 0) {
            // Someone else already revoked it or it was invalid
            throw new RuntimeException("Refresh token is missing, expired, or revoked");
        }

        // Get userId from the token we found (before it was revoked)
        String userId = existingRefresh.getUserId();

        // Generate new tokens
        String newRefreshToken = UUID.randomUUID().toString();
        String newAccessToken = UUID.randomUUID().toString();

        // Save new refresh token
        Token newRefreshTokenObj = new Token();
        newRefreshTokenObj.setTokenValue(newRefreshToken);
        newRefreshTokenObj.setUserId(userId);
        newRefreshTokenObj.setTokenType("REFRESH");
        newRefreshTokenObj.setIssuedAt(Instant.now());
        newRefreshTokenObj.setExpiresAt(Instant.now().plus(1, ChronoUnit.DAYS));
        newRefreshTokenObj.setRevoked(false);
        newRefreshTokenObj.setConsumed(false);
        tokenRepository.save(newRefreshTokenObj);

        // Save new access token
        Token newAccess = new Token();
        newAccess.setTokenValue(newAccessToken);
        newAccess.setUserId(userId);
        newAccess.setTokenType("ACCESS");
        newAccess.setIssuedAt(Instant.now());
        newAccess.setExpiresAt(Instant.now().plusMinutes(10));
        newAccess.setRevoked(false);
        newAccess.setConsumed(false);
        tokenRepository.save(newAccess);

        return new RenewResponse(newAccessToken, newRefreshToken);
    }

    // Validate and consume one-time token
    @Transactional
    public boolean validateOneTimeToken(String tokenValue) {
        Token oneTimeToken = tokenRepository.findByTokenValueAndTokenType(tokenValue, "ONETIME")
                .orElse(null);

        if (oneTimeToken == null) {
            return false;
        }

        if (oneTimeToken.isRevoked()) {
            return false;
        }
        if (oneTimeToken.isConsumed()) {
            return false;
        }
        if (oneTimeToken.getExpiresAt().isBefore(Instant.now())) {
            return false;
        }

        // All checks passed - atomically mark as consumed
        oneTimeToken.setConsumed(true);
        tokenRepository.save(oneTimeToken);
        return true;
    }

    // Logout - first validate the access token, then revoke all tokens for user
    @Transactional
    public void logout(String accessTokenValue) {
        // Find the access token to get the user_id
        Token accessToken = tokenRepository.findByTokenValueAndTokenType(accessTokenValue, "ACCESS")
                .orElse(null);

        if (accessToken == null) {
            throw new RuntimeException("Access token not found");
        }

        if (accessToken.isRevoked()) {
            throw new RuntimeException("Access token is revoked");
        }

        Instant now = Instant.now();
        if (accessToken.getExpiresAt().isBefore(now)) {
            throw new RuntimeException("Access token is expired");
        }

        // Revoke all tokens for this user
        String userId = accessToken.getUserId();
        List<Token> userTokens = tokenRepository.findByUserId(userId);
        for (Token token : userTokens) {
            token.setRevoked(true);
            tokenRepository.save(token);
        }
    }

    public static class IssueTokensResponse {
        private String accessToken;
        private String refreshToken;
        private String oneTimeToken;

        public IssueTokensResponse(String accessToken, String refreshToken, String oneTimeToken) {
            this.accessToken = accessToken;
            this.refreshToken = refreshToken;
            this.oneTimeToken = oneTimeToken;
        }
        public String getAccessToken() { return accessToken; }
        public String getRefreshToken() { return refreshToken; }
        public String getOneTimeToken() { return oneTimeToken; }
    }

    public static class RenewResponse {
        private String accessToken;
        private String refreshToken;

        public RenewResponse(String accessToken, String refreshToken) {
            this.accessToken = accessToken;
            this.refreshToken = refreshToken;
        }
        public String getAccessToken() { return accessToken; }
        public String getRefreshToken() { return refreshToken; }
    }
}

